def mru_cache(maxsize=128, typed=False) -> Callable[[Callable], Callable]:
    cache: Dict[int, Callable] = {}
    counter: Dict[int, int] = {}

    def memoized_call(func):
        nonlocal cache, counter

        @functools.wraps(func)
        def inner(*args, **kwargs):
            if id(func) in cache:
                if id(args) in cache[id(func)] and id(kwargs) in cache[id(func)][id(args)]:
                    result = cache[id(func)][id(args)][id(kwargs)]
                    counter[id(func)][id(args)][id(kwargs)] += 1
                else:
                    result = func(*args, **kwargs)
                    cache[id(func)][id(args)] = {id(kwargs): result}
                    counter[id(func)][id(args)] = {id(kwargs): 1}
                if len(cache[id(func)]) > maxsize:
                    least_used_id = min(cache[id(func)], key=lambda k: counter[id(func)][k])
                    del cache[id(func)][least_used_id]
                    del counter[id(func)][least_used_id]
                return result
            else:
                result = func(*args, **kwargs)
                cache[id(func)] = {id(args): {id(kwargs): result}}
                counter[id(func)] = {id(args): {id(kwargs): 1}}
                if len(cache[id(func)]) > maxsize:
                    least_used_id = min(cache[id(func)], key=lambda k: counter[id(func)][k])
                    del cache[id(func)][least_used_id]
                    del counter[id(func)][least_used_id]
                return result

        return inner

    return memoized_call

