def parse_frequency(frequency):
    if frequency is None or frequency.lower() == 'always':
        return None
    matches = re.match(r'(\d+)\s*(day|week|month|year)', frequency)
    if not matches:
        raise ValueError("Invalid frequency format")
    number = int(matches.group(1))
    units = matches.group(2).lower()
    units_map = {'day': timedelta(days=number), 'week': timedelta(weeks=number), 'month': timedelta(days=number * 30), 'year': timedelta(days=number * 365)}
