from typing import Set, Optional

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    # Initialize the set of roots if not provided
    if roots is None:
        roots = set()

    # Initialize the set of visited nodes
    visited = set()

    # Iterate over all nodes in the graph
    for node in graph.subjects():
        # If the node is not visited, it is a root
        if node not in visited:
            # Add the node to the set of visited nodes
            visited.add(node)

            # Check if the current node is a root based on the given property
            if graph.predecessors(node).isdisjoint(prop):
                # If it is, add the node to the set of roots
                roots.add(node)

    return roots

