def get_plugin_spec_flatten_dict(plugin_dir):
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Plugin directory {plugin_dir} does not exist")

    flatten_dict = {}
    files = os.listdir(plugin_dir)

    for file_name in files:
        file_path = os.path.join(plugin_dir, file_name)
        if os.path.isfile(file_path) and file_name.endswith('.yml'):
            with open(file_path, 'r', encoding='utf8') as file:
                file_content = file.read()
                yaml_dict = yaml.safe_load(file_content)
                flatten_dict.update(yaml_dict)

    # Flatten the dictionary by recursively processing nested dictionaries
    def flatten_dict_recurse(d, prefix=''):
        for key, value in d.items():
            if isinstance(value, dict):
                flatten_dict_recurse(value, prefix + key + '.')
            else:
                flatten_dict[prefix + key] = value

    flatten_dict_recurse(flatten_dict)

    return flatten_dict

